llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Prochlorperazine, the closest phenothiazine analogue, has absolute oral bioavailability of 12.5% in healthy volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Fluphenazine, a phenothiazine with a similar tricyclic core and basic side chain, has geometric mean absolute oral bioavailability of 2.7% after immediate-release oral dosing in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A CF3-substituted N-methylpiperazine-propyl phenothiazine analogue shows small and erratic systemic bioavailability (mean 6.0%, range 2–8%), well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Prothipendyl, a related tricyclic antipsychotic, is rapidly absorbed but has low absolute oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Revefenacin, which contains a piperidine carboxamide and polar groups, has absolute oral bioavailability <3%, supporting that the query's polar piperidine carboxamide and methylsulfonyl features are compatible with low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Levomepromazine, a phenothiazine with a methoxy and dimethylamino-propyl side chain, has reported absolute oral bioavailability of 30–70%, above the threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pridopidine, a piperidine with a methylsulfonyl phenyl group, has high oral availability in humans, suggesting the methylsulfonyl-piperidine motif alone is not necessarily low-F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phenothiazine antipsychotic analogue with a methylsulfonyl and piperidine carboxamide side chain. The closest experimental analogues—prochlorperazine, fluphenazine, and the CF3-piperazine phenothiazine—all show absolute oral bioavailability below 20% in humans (2.7–12.5%), indicating extensive first-pass metabolism or poor absorption. Less-similar high-F compounds such as levomepromazine and pridopidine do not override this consistent low-F pattern. Prediction: low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "The impact of the primary amide and methylsulfonyl substituents on absorption and first-pass metabolism is not directly measured.",
    "Transporter and metabolic stability data for the query are unavailable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

